#!/bin/bash
# run_daily_little_prof_replay.sh — Between-survey daily forward for Little Professor (replay).
# Generated by install.py from slopes/little_prof_replay/slope_config.toml
#
# Runs every morning after yesterday's station data is available. Does NOT
# resample, recluster or rewrite SMETs; those happen in run_little_prof_replay.sh
# when a new survey lands.
#
#   1. aws_ingest      fetch the latest station records into the parquet cache
#   2. smet_append     append observations to now (and drop NWP rows an older
#                      version wrote into observed SMETs)
#   3. nwp_ingest      write per-cluster forecast SMETs (input/smet_forecast/,
#                      PSUM from WRF) from T_stable to +48 h; observed SMETs
#                      are not touched
#   4. SNOWPACK daily cycle (snowpack_cycle.py): restart from the daily
#      anchor (yesterday's T_stable, never the +48 h forecast state), run to
#      today's T_stable, save the new anchor, replace the main Zarr after the
#      old anchor, run the forecast into the separate forecast store
#   5. analyze, then scenarios unless --no-scenarios
#   6. runout on the published set (runout_step.py) unless --no-runout
#
# Usage:
#   ./run_daily_little_prof_replay.sh
#   ./run_daily_little_prof_replay.sh --snapshot 2026-02-15
#   ./run_daily_little_prof_replay.sh --no-nwp
#   ./run_daily_little_prof_replay.sh --no-scenarios
#   ./run_daily_little_prof_replay.sh --no-runout
#   ./run_daily_little_prof_replay.sh --dry-run        # report SMET appends only
#
# Cron: the lines install.py prints ([cron] daily_hour_utc, under the same
# flock as the survey poll so the two never overlap).

set -euo pipefail

PROJECT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TOML=$PROJECT_DIR/slopes/little_prof_replay/slope_config.toml
ANALYSIS="python $PROJECT_DIR/src/avachain/analysis_pipeline.py --toml $TOML"
AWS="python $PROJECT_DIR/src/avachain/aws_ingest.py --toml $TOML"
SMET_APPEND="python $PROJECT_DIR/src/avachain/smet_append.py --toml $TOML"
NWP="python $PROJECT_DIR/src/avachain/nwp_ingest.py --toml $TOML"
CYCLE="python $PROJECT_DIR/src/avachain/snowpack_cycle.py --toml $TOML"
# Alerts ([alerts] email in the TOML; prints only when none). Never fails.
ALERT="python $PROJECT_DIR/src/avachain/alerts.py --toml $TOML send"
VENV=$PROJECT_DIR/.venv/bin/activate
# Every directory comes from the TOML (config.py --print-paths sets AVA_*),
# never from $PROJECT_DIR/outputs/...: a deployment relocates them.
source "$VENV"
# Assign first: a failing config.py inside eval "$(...)" would not trip set -e.
AVA_PATHS=$(python $PROJECT_DIR/src/avachain/config.py --toml $TOML --print-paths)
eval "$AVA_PATHS"
SLOPE_DIR=${SLOPE_DIR:-$AVA_SLOPE_DIR}
export SLOPE_DIR
LOG_DIR=$AVA_LOGS_DIR

SNAPSHOT_DATE=""
NO_NWP=0
NO_SCENARIOS=0
NO_RUNOUT=0
DRY_RUN=0

while [[ $# -gt 0 ]]; do
    case "$1" in
        --snapshot)     SNAPSHOT_DATE="$2"; shift 2 ;;
        --no-nwp)       NO_NWP=1; shift ;;
        --no-scenarios) NO_SCENARIOS=1; shift ;;
        --no-runout)    NO_RUNOUT=1; shift ;;
        --dry-run)      DRY_RUN=1; shift ;;
        *)              echo "Unknown arg: $1"; exit 1 ;;
    esac
done

mkdir -p "$LOG_DIR"
TIMESTAMP=$(date +%Y%m%d_%H%M%S)
LOGFILE="$LOG_DIR/daily_${TIMESTAMP}.log"
exec > >(tee -a "$LOGFILE") 2>&1

# A failed daily run used to leave only its log. Alert on any non-zero exit,
# naming the last step it reached. Signals exit 128+n so a kill is a failure.
_daily_exit() {
    local rc=$?
    [[ $rc -eq 0 ]] && return
    local step
    step=$(grep '>>> Step' "$LOGFILE" 2>/dev/null | tail -1 | sed 's/^>>> //')
    $ALERT --subject "daily run FAILED (exit $rc) at ${step:-start}" --log "$LOGFILE" || true
}
trap _daily_exit EXIT
trap 'exit 129' HUP; trap 'exit 130' INT; trap 'exit 143' TERM

echo "============================================================"
echo "  Little Professor (replay) — Daily Forward Pipeline"
echo "  Started: $(date)"
echo "  As-of:   ${AVACHAIN_AS_OF:-live}"
echo "  No-NWP:  $NO_NWP   Dry-run: $DRY_RUN"
echo "  Log:     $LOGFILE"
echo "============================================================"
echo ""

cd "$PROJECT_DIR"

SECONDS=0
SNAPSHOT_ARG=""
[[ -n "$SNAPSHOT_DATE" ]] && SNAPSHOT_ARG="--snapshot-date $SNAPSHOT_DATE"

echo ">>> Step 1: Fetch latest station data"
step1_start=$SECONDS
$AWS
step1_elapsed=$((SECONDS - step1_start))
echo ""

echo ">>> Step 2: Append observations to cluster SMETs"
step2_start=$SECONDS
if [[ $DRY_RUN -eq 1 ]]; then
    $SMET_APPEND --dry-run
    echo "Dry run: stopping before NWP and SNOWPACK."
    exit 0
fi
$SMET_APPEND
step2_elapsed=$((SECONDS - step2_start))
echo ""

echo ">>> Step 3: NWP forecast extension"
step3_start=$SECONDS
NWP_EDATE=""
STABLE_TS=""
if [[ $NO_NWP -eq 0 ]]; then
    # T_stable only when nwp_ingest wrote the forecast SMETs: otherwise the
    # forecast pass would run on missing or stale ones.
    NWP_OK=1
    $NWP --lead-hours 48 || { NWP_OK=0; echo "    WARNING: nwp_ingest failed — continuing without NWP extension"; }
    _ts_output=""
    if [[ $NWP_OK -eq 1 ]]; then
    _ts_output=$(python3 -c "
import sys; sys.path.insert(0, '$PROJECT_DIR/src/avachain')
from nwp_ingest import get_stable_ts
from config import ProjectConfig
from pathlib import Path
import pandas as pd
cfg = ProjectConfig.from_toml(Path('$TOML'))
wrf = Path(cfg.wrf_smet_file) if cfg.wrf_smet_file else None
if wrf and wrf.exists():
    ts = get_stable_ts(wrf)
    if ts:
        print(ts.strftime('%Y-%m-%dT%H:%M'),
              (ts + pd.Timedelta(hours=48)).strftime('%Y-%m-%dT%H:%M'))
" 2>/dev/null)
    fi
    if [[ -n "$_ts_output" ]]; then
        STABLE_TS=$(echo "$_ts_output" | cut -d' ' -f1)
        NWP_EDATE=$(echo "$_ts_output" | cut -d' ' -f2)
        echo "    T_stable  = $STABLE_TS"
        echo "    NWP EDATE = $NWP_EDATE (T_stable + 48h)"
    else
        echo "    WRF not available; observed run only"
    fi
else
    echo "    Skipped (--no-nwp)"
fi
step3_elapsed=$((SECONDS - step3_start))
echo ""

echo ">>> Step 4: SNOWPACK daily cycle (restart from the daily anchor)"
step4_start=$SECONDS
CYCLE_ARGS="daily"
[[ -n "$STABLE_TS" ]] && CYCLE_ARGS="$CYCLE_ARGS --stable-ts $STABLE_TS --nwp-edate $NWP_EDATE"
$CYCLE $CYCLE_ARGS
step4_elapsed=$((SECONDS - step4_start))
echo ""

echo ">>> Step 5: Analysis + scenario generation"
step5_start=$SECONDS
$ANALYSIS analyze $SNAPSHOT_ARG
if [[ $NO_SCENARIOS -eq 0 ]]; then
    $ANALYSIS scenarios $SNAPSHOT_ARG
else
    echo "    Scenarios skipped (--no-scenarios)"
fi
step5_elapsed=$((SECONDS - step5_start))
echo ""

echo ">>> Step 6: Runout (com1DFA) on the published release set"
step6_start=$SECONDS
RUNOUT_STATUS="skipped"
if [[ $NO_SCENARIOS -eq 0 && $NO_RUNOUT -eq 0 ]]; then
    CURRENT_STEP="Step 6: Runout"
    # A runout failure does not fail the run: snowpack and release succeeded
    # and are published, and a FAILED survey would redo SNOWPACK to retry
    # runout (Ron, 2026-11-04). A kill still ends FAILED (signal traps).
    if python $PROJECT_DIR/src/avachain/runout_step.py --toml $TOML $SNAPSHOT_ARG; then
        RUNOUT_STATUS="ok"
    else
        RUNOUT_STATUS="FAILED (exit $?)"
        echo "WARNING: runout $RUNOUT_STATUS. The run stays successful. Rerun runout alone:"
        echo "    python $PROJECT_DIR/src/avachain/runout_step.py --toml $TOML $SNAPSHOT_ARG"
        $ALERT --subject "runout $RUNOUT_STATUS"             --body "Snowpack and release finished and are published; the run stays successful. Rerun runout alone: python $PROJECT_DIR/src/avachain/runout_step.py --toml $TOML $SNAPSHOT_ARG"             --log "$LOGFILE" || true
    fi
else
    echo "    Runout skipped (--no-runout or --no-scenarios)"
fi
step6_elapsed=$((SECONDS - step6_start))
echo ""


total_elapsed=$SECONDS
echo "============================================================"
echo "  Daily forward complete"
echo "  Finished: $(date)"
echo "  Total:    $((total_elapsed / 3600))h $(((total_elapsed % 3600) / 60))m $((total_elapsed % 60))s"
echo "  Step 1 (aws_ingest):  $((step1_elapsed / 60))m $((step1_elapsed % 60))s"
echo "  Step 2 (smet_append): $((step2_elapsed / 60))m $((step2_elapsed % 60))s"
echo "  Step 3 (nwp_ingest):  $((step3_elapsed / 60))m $((step3_elapsed % 60))s"
echo "  Step 4 (SNOWPACK):    $((step4_elapsed / 60))m $((step4_elapsed % 60))s"
echo "  Step 5 (analysis):    $((step5_elapsed / 60))m $((step5_elapsed % 60))s"
echo "  Step 6 (runout):      $((step6_elapsed / 60))m $((step6_elapsed % 60))s  $RUNOUT_STATUS"
echo "  Log:       $LOGFILE"
echo "============================================================"
